    long seedValue(){try{return Long.parseLong(seed.getText().trim());}catch(NumberFormatException e){return seed.getText().hashCode();}}
    void openNodes(){if(world==null){status.setText("Wait for terrain generation to finish, then open Nodes.");return;}try{if(graphEditor==null)graphEditor=new GraphEditor(this);if(!graphEditor.isVisible())graphEditor.setLocationRelativeTo(this);graphEditor.setVisible(true);graphEditor.toFront();graphEditor.requestFocus();graphEditor.queuePreview();}catch(RuntimeException e){JOptionPane.showMessageDialog(this,"Could not open the node editor: "+e.getMessage(),"Node editor error",JOptionPane.ERROR_MESSAGE);}}
