    void buildGraph(TerrainGraph recipe){try{recipe.validateStructure();recipe.requireInputs(recipe.output(),new HashSet<>());}catch(IllegalArgumentException e){JOptionPane.showMessageDialog(graphEditor,e.getMessage(),"Incomplete graph",JOptionPane.WARNING_MESSAGE);return;}if(!discardChanges())return;int n=Integer.parseInt((String)size.getSelectedItem()),water=sea.getValue();long seed=seedValue();TerrainGenerator.Settings settings=generationSettings();String layout=(String)shape.getSelectedItem();int amplitude=relief.getValue();if(n==16384&&world!=null&&world.size>2048){world=null;undo.clear();redo.clear();map.invalidateTerrain();}task(n==16384?"Building large map into editor…":"Building terrain graph…",()->{World w;if(n==16384){w=LargeWorldBuilder.buildIntoEditor(recipe,seed,water,done->SwingUtilities.invokeLater(()->status.setText("Building map · "+done+" / 1024 regions")));}else{TerrainGraph.Result result=recipe.evaluate(n,n,water,seed,recipe.output(),()->Thread.currentThread().isInterrupted());w=new World(n,water,seed);w.height=result.output();w.environment=result.environment();}w.settings=settings;w.graph=recipe;w.recipeShape=layout;w.recipeRelief=amplitude;SwingUtilities.invokeLater(()->{world=w;projectFile=null;undo.clear();redo.clear();clearRecovery();map.fit();changed();worldReplaced();});});}
