    void setGenerationSettings(TerrainGenerator.Settings s){terrainScale.setValue(s.scale());octaves.setValue(s.octaves());roughness.setValue(s.roughness());ridges.setValue(s.ridges());warp.setValue(s.warp());islandSize.setValue(s.islandSize());aspect.setValue(s.aspect());rotation.setValue(s.rotation());oceanDepth.setValue(s.oceanDepth());terraces.setValue(s.terraces());plateau.setValue(s.plateau());beach.setValue(s.beach());snow.setValue(s.snow());cliff.setValue(s.cliff());generationErosion.setValue(s.erosion());rockSlopes.setSelected(s.rockSlopes());}
    void applyPreset(String name){applyingSettings=true;try{TerrainGenerator.Preset p=TerrainGenerator.preset(name);shape.setSelectedItem(p.shape());sea.setValue(p.sea());relief.setValue(p.relief());setGenerationSettings(p.settings());preset.setSelectedItem(name);}finally{applyingSettings=false;}}
    static void theme()throws Exception{for(UIManager.LookAndFeelInfo info:UIManager.getInstalledLookAndFeels())if(info.getName().equals("Nimbus")){UIManager.setLookAndFeel(info.getClassName());break;}
        UIManager.put("control",new Color(37,46,55));UIManager.put("info",new Color(37,46,55));UIManager.put("nimbusBase",new Color(40,69,76));UIManager.put("nimbusBlueGrey",new Color(49,64,73));UIManager.put("nimbusLightBackground",new Color(28,37,45));UIManager.put("text",new Color(226,234,237));UIManager.put("nimbusSelectionBackground",new Color(40,119,109));UIManager.put("defaultFont",new Font("SansSerif",Font.PLAIN,13));}
