    static void applyBrush(World w,int px,int pz,int r,int strength,String tool,float flatten){int n=w.size;float[] old=tool.equals("Smooth")?w.height.clone():null;for(int z=Math.max(0,pz-r);z<Math.min(n,pz+r+1);z++)for(int x=Math.max(0,px-r);x<Math.min(n,px+r+1);x++){double dist=Math.hypot(x-px,z-pz);if(dist>r)continue;int i=z*n+x;float f=(float)smooth(1-dist/r),a=strength*f;switch(tool){case "Raise"->w.height[i]+=a;case "Lower"->w.height[i]-=a;case "Flatten"->w.height[i]+=(flatten-w.height[i])*f*.25f;case "River"->{float target=w.sea-2-strength*.5f;w.height[i]=Math.min(w.height[i],w.height[i]+(target-w.height[i])*f);if(f>.4)w.material[i]=2;}case "Smooth"->{float sum=0;int count=0;for(int dz=-1;dz<=1;dz++)for(int dx=-1;dx<=1;dx++){int xx=Math.max(0,Math.min(n-1,x+dx)),zz=Math.max(0,Math.min(n-1,z+dz));sum+=old[zz*n+xx];count++;}w.height[i]+=(sum/count-w.height[i])*f*.6f;}default->w.material[i]=(byte)(tool.equals("Natural")?0:tool.equals("Grass")?1:tool.equals("Sand")?2:tool.equals("Stone")?3:4);}w.height[i]=Math.max(-60,Math.min(1024,w.height[i]));}}
