    static Tag b(int v){return new Tag(1,(byte)v);}static Tag i(int v){return new Tag(3,v);}static Tag l(long v){return new Tag(4,v);}static Tag str(String v){return new Tag(8,v);}static Tag compound(Map<String,Tag> v){return new Tag(10,v);}static Tag list(int type,List<?> v){return new Tag(9,new Object[]{type,v});}
