    @SuppressWarnings("unchecked") static void payload(DataOutputStream d,Tag t)throws IOException{switch(t.type){case 1->d.writeByte((Byte)t.value);case 3->d.writeInt((Integer)t.value);case 4->d.writeLong((Long)t.value);case 8->d.writeUTF((String)t.value);case 9->{Object[] v=(Object[])t.value;int type=(Integer)v[0];List<?> vals=(List<?>)v[1];d.writeByte(type);d.writeInt(vals.size());for(Object val:vals)payload(d,new Tag(type,val));}case 10->{for(var e:((Map<String,Tag>)t.value).entrySet()){d.writeByte(e.getValue().type);d.writeUTF(e.getKey());payload(d,e.getValue());}d.writeByte(0);}case 12->{long[] v=(long[])t.value;d.writeInt(v.length);for(long a:v)d.writeLong(a);}default->throw new IOException("Unsupported NBT");}}
