        for(int sy=-4;sy<w.buildHeight/16-4;sy++){int uniform=sy*16>maxTop?0:sy>-4&&sy*16+15<minSolid?(sy<0?2:3):-1;if(uniform>=0){sections.add(tags("Y",b(sy),"block_states",compound(tags("palette",list(10,List.of(tags("Name",str("minecraft:"+blocks[uniform])))))),"biomes",compound(biomeData)));continue;}int[] vals=new int[4096];for(int y=0;y<16;y++)for(int z=0;z<16;z++)for(int x=0;x<16;x++){int index=z*16+x,h=columnHeight[index],yy=sy*16+y,mat=columnSurface[index],water=columnWater[index],snow=columnSnow[index],ice=columnIce[index],v=0;
            v=ExportBlocks.block(h,mat,water,snow,ice,columnGlacier[index],yy,columnSoil[index],cx*16+x+originX,cz*16+z+originZ,w.seed);
            if(treeBlocks!=null&&treeBlocks[(yy+64)*256+z*16+x]!=0)v=treeBlocks[(yy+64)*256+z*16+x];else if(v==0&&yy==h+1&&decorLow[index]!=0)v=decorLow[index];else if(v==0&&yy==h+2&&decorHigh[index]!=0&&(treeBlocks==null||treeBlocks[(yy-1+64)*256+z*16+x]==0))v=decorHigh[index];vals[y*256+z*16+x]=v;
        }
        LinkedHashMap<Integer,Integer> used=new LinkedHashMap<>();for(int v:vals)used.computeIfAbsent(v,k->used.size());List<Map<String,Tag>> palette=new ArrayList<>();for(int id:used.keySet()){Map<String,Tag> block=id>=GroundCover.BASE?GroundCover.stateTag(id):id>=1000000?tags("Name",str("minecraft:"+RiverBanks.EXTRA_BLOCKS[id-1000000])):id>=22?TreeLibrary.stateTag(id):tags("Name",str("minecraft:"+(id==21?"grass_block":id>=13?"snow":blocks[id])));if(id==5||id==21)block.put("Properties",compound(tags("snowy",str(id==21?"true":"false"))));if(id==7)block.put("Properties",compound(tags("level",str("0"))));if(id>=13&&id<=20)block.put("Properties",compound(tags("layers",str(Integer.toString(id-12)))));palette.add(block);}Map<String,Tag> states=tags("palette",list(10,palette));if(used.size()>1){for(int a=0;a<vals.length;a++)vals[a]=used.get(vals[a]);states.put("data",new Tag(12,pack(vals,Math.max(4,32-Integer.numberOfLeadingZeros(used.size()-1)))));}
        sections.add(tags("Y",b(sy),"block_states",compound(states),"biomes",compound(biomeData)));}
        int[] heights=new int[256],motion=new int[256];for(int z=0;z<16;z++)for(int x=0;x<16;x++){int index=z*16+x;heights[index]=Math.max(columnWater[index],columnHeight[index]+(columnSnow[index]>0?1:0)+(decorHigh[index]!=0?2:decorLow[index]!=0?1:0))+65;motion[index]=Math.max(columnWater[index],columnHeight[index]+(columnSnow[index]==8?1:0))+65;if(treeBlocks!=null)for(int yy=w.buildHeight-65;yy>=-64;yy--)if(treeBlocks[(yy+64)*256+index]!=0){heights[index]=Math.max(heights[index],yy+65);motion[index]=Math.max(motion[index],yy+65);break;}}
        return nbt(tags("DataVersion",i(3700),"xPos",i(cx+originX/16),"zPos",i(cz+originZ/16),"yPos",i(-4),"Status",str("minecraft:full"),"LastUpdate",l(0),"InhabitedTime",l(0),"isLightOn",b(0),"sections",list(10,sections),"block_entities",list(10,List.of()),"block_ticks",list(10,List.of()),"fluid_ticks",list(10,List.of()),"PostProcessing",list(9,java.util.stream.IntStream.range(0,w.buildHeight/16).mapToObj(v->new Object[]{2,List.of()}).toList()),"Heightmaps",compound(tags("WORLD_SURFACE",new Tag(12,pack(heights,ExtendedHeight.heightmapBits(w.buildHeight))),"MOTION_BLOCKING",new Tag(12,pack(motion,ExtendedHeight.heightmapBits(w.buildHeight)))))));
