    static void writeWorld(World w,Path dest)throws IOException{if(Files.exists(dest))throw new IOException("Folder already exists. Choose a new world name.");ExtendedHeight.configure(w);Path parent=dest.toAbsolutePath().getParent();Files.createDirectories(parent);Path temp=Files.createTempDirectory(parent,".terraforge-export-");boolean success=false;try{Path region=Files.createDirectory(temp.resolve("region"));TreeLibrary.SpatialIndex forest=new TreeLibrary.SpatialIndex(w);int count=w.size/16;for(int rz=0;rz*32<count;rz++)for(int rx=0;rx*32<count;rx++){try(RandomAccessFile f=new RandomAccessFile(region.resolve("r."+rx+"."+rz+".mca").toFile(),"rw")){f.setLength(8192);int sector=2;for(int z=0;z<32&&rz*32+z<count;z++)for(int x=0;x<32&&rx*32+x<count;x++){byte[] data=chunk(w,rx*32+x,rz*32+z,forest);ByteArrayOutputStream zip=new ByteArrayOutputStream();try(DeflaterOutputStream out=new DeflaterOutputStream(zip)){out.write(data);}byte[] compressed=zip.toByteArray();int sectors=(compressed.length+5+4095)/4096;f.seek((z*32+x)*4L);f.writeInt((sector<<8)|sectors);f.seek(4096+(z*32+x)*4L);f.writeInt((int)(System.currentTimeMillis()/1000));f.seek(sector*4096L);f.writeInt(compressed.length+1);f.writeByte(2);f.write(compressed);sector+=sectors;f.setLength(sector*4096L);}}}
        int sx=w.size/2,sz=w.size/2;int best=-1000;for(int z=8;z<w.size-8;z+=4)for(int x=8;x<w.size-8;x+=4){int h=w.h(x,z);if(h>w.waterY(x,z)+2&&h<140&&!forest.covered(x,z)){int score=-(Math.abs(x-w.size/2)+Math.abs(z-w.size/2));if(score>best){best=score;sx=x;sz=z;}}}
        Map<String,Tag> dims=tags("minecraft:overworld",compound(tags("type",str(w.buildHeight>384?ExtendedHeight.type(w.buildHeight):"minecraft:overworld"),"generator",compound(tags("type",str("minecraft:flat"),"settings",compound(tags("biome",str("minecraft:ocean"),"features",b(0),"lakes",b(0),"structure_overrides",list(8,List.of()),"layers",list(10,List.of(tags("height",i(1),"block",str("minecraft:bedrock")),tags("height",i(w.sea+64-27),"block",str("minecraft:stone")),tags("height",i(3),"block",str("minecraft:sand")),tags("height",i(24),"block",str("minecraft:water")))))))))),"minecraft:the_nether",compound(tags("type",str("minecraft:the_nether"),"generator",compound(tags("type",str("minecraft:noise"),"settings",str("minecraft:nether"),"biome_source",compound(tags("type",str("minecraft:multi_noise"),"preset",str("minecraft:nether"))))))),"minecraft:the_end",compound(tags("type",str("minecraft:the_end"),"generator",compound(tags("type",str("minecraft:noise"),"settings",str("minecraft:end"),"biome_source",compound(tags("type",str("minecraft:the_end"))))))));
        Map<String,Tag> data=tags("DataVersion",i(3700),"version",i(19133),"Version",compound(tags("Id",i(3700),"Name",str("1.20.4"),"Series",str("main"),"Snapshot",b(0))),"LevelName",str(dest.getFileName().toString()),"GameType",i(1),"Difficulty",b(2),"hardcore",b(0),"allowCommands",b(1),"initialized",b(1),"SpawnX",i(w.exportSpawnX>=0?w.exportSpawnX:sx),"SpawnY",i(w.exportSpawnY>=0?w.exportSpawnY:forest.topAt(sx,sz)+2),"SpawnZ",i(w.exportSpawnZ>=0?w.exportSpawnZ:sz),"Time",l(0),"DayTime",l(1000),"LastPlayed",l(System.currentTimeMillis()),"WorldGenSettings",compound(tags("seed",l(w.seed),"generate_features",b(0),"bonus_chest",b(0),"dimensions",compound(dims))));
        if(w.buildHeight>384){ExtendedHeight.writePack(temp,w.buildHeight);data.put("DataPacks",compound(tags("Enabled",list(8,List.of("vanilla","file/terraforge_height")),"Disabled",list(8,List.of()))));}try(GZIPOutputStream out=new GZIPOutputStream(Files.newOutputStream(temp.resolve("level.dat")))){out.write(nbt(tags("Data",compound(data))));}Files.writeString(temp.resolve("TerraForge.txt"),"Generated for Minecraft Java 1.20.4. Custom terrain: "+w.size+" x "+w.size+" blocks at x/z 0. Beyond the custom map Minecraft generates ocean at the same sea level. Creative mode. No generated buildings, ores or caves. Tree scatter placements: "+w.environment.trees.size()+".\n");Files.move(temp,dest);success=true;}finally{if(!success){try(var paths=Files.walk(temp)){for(Path p:paths.sorted(Comparator.reverseOrder()).toList())Files.deleteIfExists(p);}}}}
    public static void main(String[] args)throws Exception{if(args.length>0&&args[0].equals("--version")){System.out.println("TerraForge "+VERSION);return;}if(args.length>1&&args[0].equals("--build-large-graph")){TerrainGraph graph=GraphEditor.readFile(Path.of(args[1]));theme();SwingUtilities.invokeLater(()->{TerraForge app=new TerraForge();app.setVisible(true);boolean[] started={false};javax.swing.Timer monitor=new javax.swing.Timer(300,null);monitor.addActionListener(e->{if(!started[0]&&!app.busy&&app.world!=null){started[0]=true;app.size.setSelectedItem("16384");app.seed.setText(args.length>2?args[2]:"2024");app.sea.setValue(62);app.dirty=false;app.buildGraph(graph);}else if(started[0]&&!app.busy){monitor.stop();if(app.world.size==16384){System.out.println("BUILD_READY: 16384 × 16384 loaded in editor; trees="+app.world.environment.trees.size());try{BufferedImage image=new BufferedImage(app.getWidth(),app.getHeight(),BufferedImage.TYPE_INT_RGB);Graphics2D graphics=image.createGraphics();app.paint(graphics);graphics.dispose();javax.imageio.ImageIO.write(image,"png",Path.of("large-map-built.png").toFile());}catch(IOException ex){System.out.println(ex.getMessage());}}else System.out.println("BUILD_FAILED");}});monitor.start();});return;}if(args.length>0&&args[0].equals("--smoke-test")){World w=generateWorld(32,63,2024,85,"Island");writeWorld(w,Path.of(args[1]));System.out.println("Exported 4 test chunks to "+args[1]);return;}theme();SwingUtilities.invokeLater(()->new TerraForge().setVisible(true));}
